@lru_cache(maxsize=1)
def normalized_requirement_aliases():
    """Normalize the requirements dictionary only once."""
    return {
        normalize_skill(requirement): {
            normalize_skill(skill)
            for skill in alternatives
        }
        for requirement, alternatives in REQUIREMENT_ALIASES.items()
    }


def requirement_candidates(requirement):
    """Return valid skill names that satisfy one requirement."""
    normalized = normalize_skill(requirement)

    return normalized_requirement_aliases().get(
        normalized, {normalized}
    )


def compare_skills(user_skills):
    """
    Compare user skills against all job roles.

    Score = matched requirements / total requirements * 100.
    Every requirement counts at most once.
    """
    user_skill_set = {
        normalize_skill(skill)
        for skill in user_skills
        if skill and str(skill).strip()
    }

    scores = {}

    for role, required_skills in JOB_TITLE_SKILL_MAP.items():
        # Deduplicate requirements after normalization.
        unique_requirements = list(dict.fromkeys(
            normalize_skill(skill)
            for skill in required_skills
        ))

        matched = []
        missing = []
        evidence_map = {}

        for requirement in unique_requirements:
            candidates = requirement_candidates(requirement)
            evidence = sorted(user_skill_set.intersection(candidates))

            if evidence:
                matched.append(requirement)
                evidence_map[requirement] = evidence
            else:
                missing.append(requirement)

        total = len(unique_requirements)
        matched_count = len(matched)

        score = round(
            matched_count / total * 100, 2
        ) if total else 0.0

        scores[role] = {
            "score": score,
            "matched_skills": matched,
            "missing_skills": missing,
            "matched_evidence": evidence_map,
            "matched_count": matched_count,
            "required_count": total,
        }

    return sorted(
        scores.items(),
        key=lambda item: item[1]["score"],
        reverse=True,
    )
